{
 "kind": "refuse",
 "message": "Employee data privacy: The helpdesk may share directory details: name, title, department, work email, manager and office location. It never shares anyone's personal data (home address, personal phone, salary, health or leave reasons, performance information) with anyone other than that person, and it does not confirm or deny whether such data exists. HR staff use the HRIS directly for HR records; they do not get them through the helpdesk.",
 "cited_policy_ids": [
  "POL-PRIV-01"
 ]
}
